parameters.query:
select to_char(last_successful_publication_date, 'YYYY-MM-DD') as last_date
from discovery_checkpoints
where id = 1;

parameters.jsCode:
// Build Email
// Collects this run's relevant papers. Returns nothing if there are none,
// so the send step does not run on empty days.

const papers = $('Prepare Row').all()
  .map(i => i.json)
  .filter(p => p.relevance_status === 'relevant');

if (papers.length === 0) return [];

const rows = papers.map(p => {
  const link = p.oa_url || p.landing_page_url || '';
  return `<li><b>${p.title}</b><br>${p.journal_name || ''} · ${p.publication_date}<br><a href="${link}">${link}</a></li>`;
}).join('');

return [{
  json: {
    subject: `IndianMatter: ${papers.length} new relevant paper(s)`,
    html: `<p>${papers.length} new relevant paper(s):</p><ol>${rows}</ol>`,
  },
}];

// Generate individual queries
// Reads json.domains from the config node.
// Outputs one item per enabled query phrase.

const domains = $input.first().json.domains;
const items = [];

for (const domain of domains) {
  if (!domain.enabled) continue;

  for (const phrase of domain.queries) {
    items.push({
      json: {
        domain_id: domain.id,
        domain_label: domain.label,
        phrase: phrase,
        search: `"${phrase}"`
      }
    });
  }
}

return items;

// Normalize Results
// Flattens OpenAlex responses into one item per paper.
// Keeps the query phrase that found each paper.

const out = [];
const queries = $('Generate Queries').all();
const pages = $input.all();

pages.forEach((item, i) => {
  const q = queries[i]?.json || {};
  const results = item.json.results || [];

  for (const w of results) {
    out.push({
      json: {
        openalex_id: w.id || null,
        doi: w.doi || null,
        title: w.title || w.display_name || null,
        publication_date: w.publication_date || null,
        publication_year: w.publication_year || null,
        journal_name: w.primary_location?.source?.display_name || null,
        journal_issn: w.primary_location?.source?.issn_l || null,
        publisher: w.primary_location?.source?.host_organization_name || null,
        open_access: w.open_access?.is_oa ?? null,
        oa_url: w.open_access?.oa_url || null,
        landing_page_url: w.primary_location?.landing_page_url || null,
        pdf_url: w.primary_location?.pdf_url || null,
        topics: (w.topics || []).map(t => t.display_name),
        keywords: (w.keywords || []).map(k => k.display_name),
        cited_by_count: w.cited_by_count ?? null,
        is_retracted: w.is_retracted ?? false,
        abstract_inverted_index: w.abstract_inverted_index || null,
        matched_domain_id: q.domain_id || null,
        matched_phrase: q.phrase || null
      }
    });
  }
});

return out;

// Deduplicate
// Keeps the first copy of each paper, matched by DOI first, then OpenAlex ID.
// Normalizes DOIs so "https://doi.org/10.x/ABC" and "10.x/abc" count as the same.

const seen = new Set();
const out = [];

const normDoi = (doi) => {
  if (!doi) return null;
  return doi
    .trim()
    .toLowerCase()
    .replace(/^https?:\/\/(dx\.)?doi\.org\//, '');
};

for (const item of $input.all()) {
  const p = item.json;
  const doi = normDoi(p.doi);
  const keys = [];
  if (doi) keys.push(`doi:${doi}`);
  if (p.openalex_id) keys.push(`oa:${p.openalex_id}`);

  if (keys.length === 0) continue;
  if (keys.some(k => seen.has(k))) continue;

  keys.forEach(k => seen.add(k));
  out.push({ json: { ...p, doi: doi || null } });
}

return out;

// Abstract Conversion
// Rebuilds plain-text abstracts from OpenAlex's abstract_inverted_index.
// Papers with no abstract keep abstract = null.

const out = [];

for (const item of $input.all()) {
  const p = { ...item.json };
  const idx = p.abstract_inverted_index;
  let abstract = null;

  if (idx && typeof idx === 'object') {
    const words = [];
    for (const [word, positions] of Object.entries(idx)) {
      for (const pos of positions) {
        words[pos] = word;
      }
    }
    abstract = words.filter(w => w !== undefined).join(' ') || null;
  }

  delete p.abstract_inverted_index;
  p.abstract = abstract;
  out.push({ json: p });
}

return out;

// Relevance Filter (v3)
// 1. Each phrase counts once per domain (no stacking from repeated matches).
// 2. Single generic matches need support from a materials-context term.
// 3. Papers with a strong domain signal in the title/keywords/topics are kept.

const THRESHOLD = 5;
const W = { title: 3, abstract: 2, keywords: 2, topics: 3 };

// Terms that show a paper is about materials science, not other fields.
const MATERIALS_CONTEXT = [
  'material', 'materials', 'crystal', 'electrolyte', 'electrolytes',
  'battery', 'batteries', 'electrode', 'cathode', 'anode', 'dft',
  'density functional', 'first principles', 'interatomic', 'alloy',
  'semiconductor', 'perovskite', 'oxide', 'chalcogenide', 'catalyst',
  'thermoelectric', 'band gap', 'lattice', 'phase'
];

const norm = (s) =>
  ' ' + (s || '')
    .toLowerCase()
    .replace(/[-_]/g, ' ')
    .replace(/[^a-z0-9+ ]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim() + ' ';

const domains = $('Domain Config').first().json.domains.filter(d => d.enabled);

const out = [];

for (const item of $input.all()) {
  const p = item.json;

  const fields = {
    title: [norm(p.title)],
    abstract: [norm(p.abstract)],
    keywords: (p.keywords || []).map(norm),
    topics: (p.topics || []).map(norm),
  };

  const allText = [...fields.title, ...fields.abstract, ...fields.keywords, ...fields.topics].join(' ');
  const hasMaterialsContext = MATERIALS_CONTEXT.some(t => allText.includes(' ' + t));

  const matchedDomains = [];
  let best = 0;

  for (const domain of domains) {
    let score = 0;
    const phrases = [];

    for (const phrase of domain.queries) {
      const q = norm(phrase);
      let w = 0;

      for (const [field, texts] of Object.entries(fields)) {
        if (texts.some(t => t.includes(q))) {
          w = Math.max(w, W[field]);
        }
      }

      // Generic phrases need materials context to count.
      const isGeneric = /^(materials? (screening|discovery|informatics|property))/.test(q.trim());
      if (w > 0 && isGeneric && !hasMaterialsContext) w = 0;

      if (w > 0) {
        score += w;
        phrases.push(phrase);
      }
    }

    // Cap per domain so one domain can't dominate on repeated phrases.
    score = Math.min(score, 6);

    if (score > 0) {
      matchedDomains.push({ id: domain.id, score, matched_phrases: phrases });
      best = Math.max(best, score);
    }
  }

  out.push({
    json: {
      ...p,
      domain_tags: matchedDomains.map(d => d.id),
      domain_scores: matchedDomains,
      relevance_score: best,
      relevance_status:
        best >= THRESHOLD ? 'relevant' : best > 0 ? 'low_relevance' : 'rejected',
    },
  });
}

return out;

// Metadata Validation
// Drops rejected papers and papers missing required fields.
// Keeps relevant and low_relevance papers. Missing optional fields are recorded, not rejected.

const out = [];

for (const item of $input.all()) {
  const p = item.json;

  if (p.relevance_status === 'rejected') continue;

  const missingRequired = [];
  if (!p.title) missingRequired.push('title');
  if (!p.publication_date) missingRequired.push('publication_date');
  if (!p.openalex_id) missingRequired.push('openalex_id');
  if (missingRequired.length > 0) continue;

  const missingOptional = [];
  if (!p.doi) missingOptional.push('doi');
  if (!p.pdf_url) missingOptional.push('pdf_url');
  if (!p.abstract) missingOptional.push('abstract');

  out.push({
    json: {
      ...p,
      metadata_status: 'valid',
      missing_optional: missingOptional,
    },
  });
}

return out;

// Prepare Row
// Outputs only the papers columns. Arrays stay arrays (stored as text[]).

const out = [];

for (const item of $input.all()) {
  const p = item.json;
  if (new Date(p.publication_date) > new Date()) continue;

  out.push({
    json: {
      openalex_id: p.openalex_id,
      doi: p.doi || null,
      title: p.title,
      abstract: p.abstract || null,
      publication_date: p.publication_date,
      publication_year: p.publication_year || null,
      journal_name: p.journal_name || null,
      journal_issn: p.journal_issn || null,
      publisher: p.publisher || null,
      open_access: p.open_access ?? null,
      oa_url: p.oa_url || null,
      landing_page_url: p.landing_page_url || null,
      pdf_url: p.pdf_url || null,
      topics: p.topics || [],
      keywords: p.keywords || [],
      domain_tags: p.domain_tags || [],
      relevance_score: p.relevance_score,
      relevance_status: p.relevance_status,
      updated_at: new Date().toISOString(),
    },
  });
}

return out;
